+Status CandidateCheckpointCodec::EncodePeerBaseline(
+    const Snapshot& snapshot, std::vector<std::byte>& output) noexcept
+{
+    try
+    {
+        static thread_local std::unique_ptr<CandidateCheckpointImage> image;
+        if (image == nullptr) image = std::make_unique<CandidateCheckpointImage>();
+        const auto decoded = Decode(snapshot, *image);
+        if (!decoded.ok()) return decoded;
+
+        static thread_local std::vector<std::byte> native;
+        static thread_local std::vector<std::byte> move_dispatch;
+        static thread_local std::vector<std::byte> secondary;
+        static thread_local std::vector<std::byte> animation;
+        static thread_local std::vector<std::byte> wind;
+        NativeCandidateRegions::CanonicalBytes(image->native, native);
+        MoveDispatchState::CanonicalBytes(image->move_dispatch, move_dispatch);
+        SecondaryEventState::CanonicalBytes(image->secondary_events, secondary);
+        CharaAnimationState::CanonicalBytes(image->chara_animation, animation);
+        wind.clear();
+        encode_wind_local(image->wind, wind);
+        if (native.empty() || move_dispatch.empty()
+            || native.size() > UINT32_MAX || move_dispatch.size() > UINT32_MAX
+            || secondary.size() > UINT32_MAX || animation.size() > UINT32_MAX
+            || wind.size() > UINT32_MAX)
+        {
+            return Status::failure(FailureCode::CapacityExceeded);
+        }
+
+        output.clear();
+        const auto total = peer_baseline_magic.size() + 2 * sizeof(std::uint32_t)
+            + 2 * sizeof(std::uint64_t) + snapshot.canonical_hash.size()
+            + 5 * (sizeof(std::uint32_t) + sizeof(std::uint64_t))
+            + sizeof(image->ucrt.algorithm_version)
+            + sizeof(image->ucrt.allowlist_version)
+            + sizeof(image->ucrt.state) + sizeof(image->ucrt.draws)
+            + sizeof(std::uint8_t) + native.size() + move_dispatch.size()
+            + secondary.size() + animation.size() + wind.size();
+        output.reserve(total);
+        append_range(output, peer_baseline_magic);
+        append(output, peer_baseline_format_version);
+        append(output, Schema::snapshot_schema_version);
+        append(output, snapshot.coordinate.generation);
+        append(output, snapshot.coordinate.frame);
+        append_range(output, snapshot.canonical_hash);
+        const auto add_section = [&output](const auto& section)
+        {
+            append(output, static_cast<std::uint32_t>(section.size()));
+            append(output, local_checksum(section));
+        };
+        add_section(native);
+        add_section(move_dispatch);
+        add_section(secondary);
+        add_section(animation);
+        add_section(wind);
+        append(output, image->ucrt.algorithm_version);
+        append(output, image->ucrt.allowlist_version);
+        append(output, image->ucrt.state);
+        append(output, image->ucrt.draws);
+        append(output, static_cast<std::uint8_t>(image->ucrt.seeded));
+        append_range(output, native);
+        append_range(output, move_dispatch);
+        append_range(output, secondary);
+        append_range(output, animation);
+        append_range(output, wind);
+        return output.size() == total ? Status::success()
+            : Status::failure(FailureCode::CaptureFailed);
+    }
+    catch (...)
+    {
+        output.clear();
+        return Status::failure(FailureCode::CapacityExceeded);
+    }
+}
