+Status CandidateCheckpointCodec::MergePeerBaseline(
+    const Snapshot& local_snapshot,
+    std::span<const std::byte> peer_payload,
+    Snapshot& output) noexcept
+{
+    std::array<std::byte, peer_baseline_magic.size()> observed_magic{};
+    std::uint32_t observed_format{}, observed_schema{};
+    FrameCoordinate coordinate{};
+    CanonicalHash expected_hash{};
+    std::array<std::uint32_t, 5> sizes{};
+    std::array<std::uint64_t, 5> checksums{};
+    UcrtRandBrokerImage ucrt{};
+    Reader reader{peer_payload};
+    if (!reader.TakeBytes(observed_magic)
+        || observed_magic != peer_baseline_magic
+        || !reader.Take(observed_format)
+        || observed_format != peer_baseline_format_version
+        || !reader.Take(observed_schema)
+        || observed_schema != Schema::snapshot_schema_version
+        || !reader.Take(coordinate.generation) || !reader.Take(coordinate.frame)
+        || coordinate != local_snapshot.coordinate
+        || !reader.TakeBytes(expected_hash))
+    {
+        return Status::failure(FailureCode::ProtocolMismatch);
+    }
+    for (std::size_t index = 0; index < sizes.size(); ++index)
+    {
+        if (!reader.Take(sizes[index]) || !reader.Take(checksums[index]))
+            return Status::failure(FailureCode::ProtocolMismatch);
+    }
+    if (sizes[0] == 0 || sizes[0] > 0x10000
+        || sizes[1] == 0 || sizes[1] > 0x10000
+        || sizes[2] > 0x1000 || sizes[3] > 0x10000
+        || sizes[4] > 0x10000
+        || !reader.Take(ucrt.algorithm_version)
+        || !reader.Take(ucrt.allowlist_version)
+        || !reader.Take(ucrt.state) || !reader.Take(ucrt.draws))
+    {
+        return Status::failure(FailureCode::CapacityExceeded);
+    }
+    std::uint8_t seeded{};
+    if (!reader.Take(seeded) || seeded > 1)
+        return Status::failure(FailureCode::ProtocolMismatch);
+    ucrt.seeded = seeded != 0;
+    std::array<std::span<const std::byte>, 5> sections{};
+    for (std::size_t index = 0; index < sections.size(); ++index)
+    {
+        sections[index] = reader.TakeView(sizes[index]);
+        if (sections[index].size() != sizes[index]
+            || local_checksum(sections[index]) != checksums[index])
+        {
+            return Status::failure(FailureCode::RestoreVerificationFailed);
+        }
+    }
+    if (!reader.Finished() || !valid_ucrt_image(ucrt))
+        return Status::failure(FailureCode::ProtocolMismatch);
+
+    try
+    {
+        static thread_local std::unique_ptr<CandidateCheckpointImage> local;
+        static thread_local std::unique_ptr<CandidateCheckpointImage> peer;
+        if (local == nullptr) local = std::make_unique<CandidateCheckpointImage>();
+        if (peer == nullptr) peer = std::make_unique<CandidateCheckpointImage>();
+        const auto local_decoded = Decode(local_snapshot, *local);
+        if (!local_decoded.ok()) return local_decoded;
+        reset_checkpoint_image(*peer);
+        peer->ucrt = ucrt;
+        auto status = NativeCandidateRegions::DecodeCanonicalBytes(
+            sections[0], peer->native);
+        if (status.ok()) status = MoveDispatchState::DecodeCanonicalBytes(
+            sections[1], peer->move_dispatch);
+        if (status.ok()) status = SecondaryEventState::DecodeCanonicalBytes(
+            sections[2], peer->secondary_events);
+        if (status.ok()) status = CharaAnimationState::DecodeCanonicalBytes(
+            sections[3], peer->chara_animation);
+        if (status.ok()) status = decode_wind_local(sections[4], peer->wind);
+        // Presentation ownership is receiver-local and is not carried by the
+        // peer package, but it participates in the complete image-generation
+        // invariant. Install it before validating the hybrid image.
+        peer->battle_audio_selector = local->battle_audio_selector;
+        if (!status.ok() || !canonical_generations_match(coordinate, *peer))
+            return status.ok()
+                ? Status::failure(FailureCode::GenerationMismatch) : status;
+
+        // Native FrameInputLog is the stock transport's process-local staging
+        // area. Keep the receiver's ownership mask, mirrors, and rolling rows;
+        // the peer-canonical hash deliberately excludes them.
+        peer->native.input_log = local->native.input_log;
+        peer->local_images = std::move(local->local_images);
+        status = EncodeCaptured(coordinate, local_snapshot.context_identity,
+            *peer, output);
+        if (!status.ok()) return status;
+        return output.canonical_hash == expected_hash
+            ? Status::success()
+            : Status::failure(FailureCode::StateHashMismatch);
+    }
+    catch (...)
+    {
+        return Status::failure(FailureCode::CapacityExceeded);
+    }
+}
 }
