+void append_peer_input_log(
+    std::vector<std::byte>& output,
+    const NativeFrameInputLogImage& input_log)
+{
+    // These value fields define the shared clock/configuration. Index 3 is
+    // LocalPlayerFlags and indices 10/11 are local current-input mirrors.
+    // The 1024 cache rows are transport staging: the owning peer publishes a
+    // row before the remote peer receives it, so hashing them would reject a
+    // healthy stock-online handoff.
+    constexpr std::array<std::size_t, 9> shared_scalar_indices{
+        0, 1, 2, 4, 5, 6, 7, 8, 9};
+    for (const auto index : shared_scalar_indices)
+    {
+        append_bytes(output,
+            input_log.scalars.data() + index * sizeof(std::uint32_t),
+            sizeof(std::uint32_t));
+    }
+}
