+Status OnlineCoordinator::PublishAuthorityBaseline(FrameCoordinate coordinate,
+    const CanonicalHash& hash, std::span<const std::byte> payload) noexcept
+{
+    constexpr std::size_t chunk_header_size =
+        2 * sizeof(std::uint64_t) + 2 * sizeof(std::uint32_t);
+    constexpr std::size_t chunk_capacity =
+        Schema::maximum_transport_payload - chunk_header_size;
+    if (state_ != OnlineState::AwaitingBaselineTarget || !contract_
+        || !local_is_baseline_authority() || !baseline_target_
+        || coordinate != *baseline_target_ || payload.empty()
+        || payload.size() > Schema::maximum_authority_baseline_payload
+        || payload.size() > (std::numeric_limits<std::uint32_t>::max)())
+    {
+        return Status::failure(FailureCode::IllegalTransition);
+    }
+    if (authority_baseline_published_)
+    {
+        return authority_baseline_coordinate_ == coordinate
+                && authority_baseline_hash_ == hash
+                && authority_baseline_expected_size_ == payload.size()
+            ? Status::success()
+            : Status::failure(FailureCode::IdentityMismatch);
+    }
+
+    const auto total = static_cast<std::uint32_t>(payload.size());
+    for (std::uint32_t offset = 0; offset < total;)
+    {
+        const auto count = (std::min)(chunk_capacity,
+            static_cast<std::size_t>(total - offset));
+        TransportMessage message{};
+        message.kind = TransportMessageKind::AuthorityBaselineChunk;
+        message.session_id = contract_->session_id;
+        if (!write_authority_baseline_chunk(message, coordinate, total, offset,
+                payload.subspan(offset, count)))
+            return fail(FailureCode::CapacityExceeded);
+        const auto sent = transport_.Send(
+            message, TransportReliability::Reliable);
+        if (!sent.ok()) return fail(transport_failure(sent));
+        offset += static_cast<std::uint32_t>(count);
+    }
+    TransportMessage commit{};
+    commit.kind = TransportMessageKind::AuthorityBaselineCommit;
+    commit.session_id = contract_->session_id;
+    if (!write_authority_baseline_control(commit, coordinate, total, hash))
+        return fail(FailureCode::CapacityExceeded);
+    const auto sent = transport_.Send(commit, TransportReliability::Reliable);
+    if (!sent.ok()) return fail(transport_failure(sent));
+    authority_baseline_coordinate_ = coordinate;
+    authority_baseline_hash_ = hash;
+    authority_baseline_expected_size_ = total;
+    authority_baseline_published_ = true;
+    return Status::success();
+}
+
+Status OnlineCoordinator::handle_authority_baseline_chunk(
+    const TransportMessage& message) noexcept
+{
+    if (state_ != OnlineState::AwaitingBaselineTarget || !contract_
+        || local_is_baseline_authority() || !baseline_target_)
+        return Status::failure(FailureCode::IllegalTransition);
+    WireReader reader(message);
+    FrameCoordinate coordinate{};
+    std::uint32_t total{}, offset{};
+    if (!reader.U64(coordinate.generation) || !reader.U64(coordinate.frame)
+        || !reader.U32(total) || !reader.U32(offset) || reader.Remaining() == 0
+        || coordinate != *baseline_target_ || total == 0
+        || total > Schema::maximum_authority_baseline_payload
+        || offset != authority_baseline_received_size_
+        || offset > total || reader.Remaining() > total - offset)
+        return Status::failure(FailureCode::ProtocolMismatch);
+    if (authority_baseline_expected_size_ == 0)
+    {
+        authority_baseline_expected_size_ = total;
+        authority_baseline_coordinate_ = coordinate;
+        authority_baseline_receive_.clear();
+    }
+    else if (authority_baseline_expected_size_ != total
+        || authority_baseline_coordinate_ != coordinate)
+        return Status::failure(FailureCode::IdentityMismatch);
+    const auto count = reader.Remaining();
+    try
+    {
+        authority_baseline_receive_.resize(
+            authority_baseline_received_size_ + count);
+    }
+    catch (...) { return Status::failure(FailureCode::CapacityExceeded); }
+    if (!reader.Blob(std::span<std::byte>{authority_baseline_receive_}.subspan(
+            authority_baseline_received_size_, count))
+        || !reader.Finished())
+        return Status::failure(FailureCode::ProtocolMismatch);
+    authority_baseline_received_size_ += static_cast<std::uint32_t>(count);
+    return Status::success();
+}
+
+Status OnlineCoordinator::handle_authority_baseline_commit(
+    const TransportMessage& message) noexcept
+{
+    if (state_ != OnlineState::AwaitingBaselineTarget || !contract_
+        || local_is_baseline_authority() || !baseline_target_)
+        return Status::failure(FailureCode::IllegalTransition);
+    FrameCoordinate coordinate{};
+    std::uint32_t total{};
+    CanonicalHash hash{};
+    if (!read_authority_baseline_control(message, coordinate, total, hash)
+        || coordinate != *baseline_target_ || total == 0
+        || total != authority_baseline_expected_size_
+        || total != authority_baseline_received_size_
+        || authority_baseline_receive_.size() != total)
+        return Status::failure(FailureCode::ProtocolMismatch);
+    if (authority_baseline_committed_)
+        return authority_baseline_coordinate_ == coordinate
+                && authority_baseline_hash_ == hash
+            ? Status::success()
+            : Status::failure(FailureCode::IdentityMismatch);
+    authority_baseline_hash_ = hash;
+    authority_baseline_committed_ = true;
+    TransportMessage ack{};
+    ack.kind = TransportMessageKind::AuthorityBaselineAck;
+    ack.session_id = contract_->session_id;
+    if (!write_authority_baseline_control(ack, coordinate, total, hash))
+        return Status::failure(FailureCode::CapacityExceeded);
+    const auto sent = transport_.Send(ack, TransportReliability::Reliable);
+    return sent.ok() ? Status::success()
+                     : Status::failure(transport_failure(sent));
+}
