+    if (state_ != OnlineState::AwaitingBaselineTarget || !contract_
+        || !local_is_baseline_authority() || !authority_baseline_published_)
+        return Status::failure(FailureCode::IllegalTransition);
+    FrameCoordinate coordinate{};
+    std::uint32_t total{};
+    CanonicalHash hash{};
+    if (!read_authority_baseline_control(message, coordinate, total, hash)
+        || coordinate != authority_baseline_coordinate_
+        || total != authority_baseline_expected_size_
+        || hash != authority_baseline_hash_)
+        return Status::failure(FailureCode::IdentityMismatch);
+    authority_baseline_ack_received_ = true;
+    return Status::success();
+}
